// support-agent.ts
const SYSTEM_PROMPT =
  'You are SupportBot. Apply the refund policy included in the context. Use the tools when needed.';

const TOOLS = [searchOrders, issueRefund, exportCustomerData];

export async function handleRequest(userMessage: string, session: Session) {
  const docs = await kb.search(userMessage, { limit: 4 }); // corpus-wide, no tenant filter
  const context = [
    SYSTEM_PROMPT,
    ...docs.map((d) => d.text), // raw text, no id, no delimiter
    userMessage,
  ].join('\n\n');

  const plan = await model(context, TOOLS); // the model picks tool and arguments
  for (const call of plan.toolCalls) {
    await runTool(call.name, call.args); // arguments trusted as sent
  }
  return plan.text;
}

const report = {
  passAllBefore: 0.62,
  passAllAfter: 0.74,
  cases: 80,
  dataset: 'golden-v3 (tuned on it for 4 weeks)',
  judge: 'eval-judge-v2 (updated last week)'
};
