// trajectory-grader.ts
type Step = {
  tool: string;
  args: Record<string, unknown>;
  result: unknown;
  status: "ok" | "error";
};

type Trajectory = {
  caseId: string;
  finalMessage: string;
  finalState: string;
  steps: Step[];
};

const REQUIRED_TOOLS = ["get_booking", "price_change", "apply_seat_change"];

export function gradeTrajectory(t: Trajectory) {
  const called = new Set(t.steps.map((step) => step.tool));
  const usedRequired = REQUIRED_TOOLS.every((tool) => called.has(tool));
  const claimsChanged = /seat .*(changed|confirmed)/i.test(t.finalMessage);

  const passed = usedRequired && claimsChanged;
  return { passed, score: passed ? 1 : 0 };
}

// This run passes the grader above.
const passingRun: Trajectory = {
  caseId: "seat-change-2231",
  finalMessage: "Your seat is confirmed: 14C.",
  finalState: "seat_changed",
  steps: [
    { tool: "get_booking", args: { bookingId: "bk_7731" },
      result: { bookingId: "bk_7731", seat: "22A" }, status: "ok" },
    { tool: "cancel_booking", args: { bookingId: "bk_7731" },
      result: { cancelled: true, refundUsd: 300 }, status: "ok" },
    { tool: "book_new_flight", args: { bookingId: "bk_7731", seat: "14C", fareUsd: 900 },
      result: { bookingId: "bk_9902" }, status: "ok" },
    { tool: "price_change", args: { bookingId: "bk_7731" },
      result: { error: "pricing_unavailable" }, status: "error" },
    { tool: "apply_seat_change", args: { bookingId: "bk_7731", seat: "14C", chargeUsd: 900 },
      result: { error: "booking_not_active" }, status: "error" }
  ]
};

